// Tests generated by Claude. Modified as needed to fit the code.
//
// API THESE TESTS ASSUME (adjust the glue below, not the tests, if names differ):
// parse(&[Token], &str) -> Ast            (no lifetime: nodes hold spans only)
// Ast { root: Node, errors: Vec<ParseError> }
// ParseError { kind: ParseErrorKind, span: Span }
// Span is half open, bytes: start..end. Every node carries one.
// Root span = whole source (0..src.len()), including trailing trivia.
// Trivia (whitespace, newlines, comments) never appears in the tree.
//
// NodeKinds: Root(Vec<Node>), List(Vec<Node>), Quote(Box<Node>), Dot, Symbol,
// Integer, Real, String, True, Nil, Missing.
// - Values are NOT stored. Text is recovered by slicing the source with the
//   span, so `shape` and `outline` take the source.
// - The parser decides Integer vs Real. A TokenKind::Integer that does not fit
//   in i32 becomes a Real node. 1e999 is a plain Real; no error.
// - Symbols `nil` and `t` (any capitalization) become Nil / True nodes.
//   `()` stays an empty List.
// - A dotted list is a normal List with a Dot node among its children. There is
//   no cons node: `cons` the function is just a symbol.
// - A Quote always has a child. If the operand is missing, the child is a
//   zero-width Missing node.
//
// ParseErrorKind variants used: MisplacedDot, QuoteMissingOperand, UnclosedList,
// UnmatchedCloseParen, UnterminatedString, UnterminatedBlockComment and
// ExtraCdrsInDottedPair (AutoCAD: "extra cdrs in dotted pair on input").
//
// Dotted-list errors: after the first element that follows the dot, everything
// up to the closing paren is "extra". ONE ExtraCdrsInDottedPair error per
// list, spanning from the start of the first extra element to the end of the
// last (a second dot counts as an extra element and gets no MisplacedDot).
//
// Errors are compared after a *stable* sort by (start, end), so errors that
// share a position keep emission order (innermost unclosed list first).
//
// RECOVERY RULE (single pass, no lookahead). While at least one list is open,
// a `(` that is the first character on its line (column 0) followed by defun /
// defun-q / defun-q-list-set / defun-q-list-ref (case-insensitive) closes ALL
// open lists, innermost first, each with an UnclosedList error at a zero-width
// span after the last non-trivia token before it. An indented or mid-line
// `(defun` does not. A later `)` that then has no open list is reported as
// UnmatchedCloseParen and dropped. A balance pre-check was considered and
// postponed.
use super::*;
use crate::document::lexer::tokenize;
use ParseErrorKind::*;

// ---------------------------------------------------------------
// support: glue is written, the two renderers are yours (they depend
// on your node layout)
// ---------------------------------------------------------------

type Err = (ParseErrorKind, usize, usize); // (kind, start, end)

fn check(src: &str, expected_tree: &str, expected_errors: &[Err]) {
    let tokens = tokenize(src);
    let ast = parse(tokens, src);
    assert_eq!(shape(&ast, src), expected_tree, "tree for {src:?}");
    let mut errs: Vec<Err> = ast
        .errors
        .iter()
        .map(|e| (e.kind, e.span.start, e.span.end))
        .collect();
    errs.sort_by_key(|&(_, start, end)| (start, end)); // stable
    assert_eq!(errs, expected_errors, "errors for {src:?}");
}

fn ok(src: &str, expected_tree: &str) {
    check(src, expected_tree, &[]);
}

/// Render the tree as a compact s-expression string. Text comes from slicing
/// `src` with the node's span.
///   Root      -> "<" children joined by " " ">"
///   List      -> "(" children joined by " " ")"
///   Quote     -> "'" + child
///   Dot       -> "."
///   Symbol    -> source text exactly as written (case preserved)
///   Integer   -> source text                 e.g. 42, -7
///   Real      -> "~" + source text           e.g. ~3.5, ~3., ~2147483648
///   String    -> source slice verbatim, quotes included
///                (an unterminated string has no closing quote)
///   Nil       -> "nil"   (canonical, whatever the source capitalization)
///   True      -> "t"     (canonical, whatever the source capitalization)
///   Missing   -> "?"     (zero-width placeholder after a lone quote)
///   Skipped   -> "{ SKIPPED }"
fn shape(ast: &Ast, src: &str) -> String {
    show(&ast.root, src)
}

fn show(node: &Node, src: &str) -> String {
    let (prefix, suffix) = node.kind.pair();
    let mut s = if let Some(prefix) = prefix {
        String::from(prefix)
    } else {
        String::new()
    };
    match &node.kind {
        NodeKind::Root(_) | NodeKind::List(_) | NodeKind::Quote(_) => s.push_str(
            &node
                .children()
                .iter()
                .map(|c| show(c, src))
                .reduce(|acc, s| format!("{acc} {s}"))
                .unwrap_or_default(),
        ),
        NodeKind::Symbol | NodeKind::Integer | NodeKind::Real | NodeKind::String => {
            s.push_str(node.span.slice(src))
        }
        NodeKind::Dot => s.push('.'),
        NodeKind::True => s.push('t'),
        NodeKind::Nil => s.push_str("nil"),
        NodeKind::Missing => s.push('?'),
        NodeKind::Skipped => s.push_str("{ SKIPPED }"),
    };
    if let Some(suffix) = suffix {
        s.push(suffix);
    }
    s
}

impl NodeKind {
    fn pair(&self) -> (Option<char>, Option<char>) {
        match self {
            Self::Root(_) => (Some('<'), Some('>')),
            Self::List(_) => (Some('('), Some(')')),
            Self::Quote(_) => (Some('\''), None),
            Self::Real => (Some('~'), None),
            _ => (None, None),
        }
    }
}

/// Preorder list of (label, start, end) for every node including Root.
/// Labels: "root" "list" "quote" "dot" "sym" "int" "real" "str" "nil" "t"
/// "missing". Dot is an ordinary child of its List.
fn outline(src: &str) -> Vec<(&'static str, usize, usize)> {
    let tokens = tokenize(src);
    let ast = parse(tokens, src);
    label(&ast.root)
}

fn label(node: &Node) -> Vec<(&'static str, usize, usize)> {
    match &node.kind {
        NodeKind::Root(nodes) => {
            let mut v = vec![("root", node.span.start, node.span.end)];
            v.extend(nodes.iter().flat_map(label));
            v
        }
        NodeKind::List(nodes) => {
            let mut v = vec![("list", node.span.start, node.span.end)];
            v.extend(nodes.iter().flat_map(label));
            v
        }
        NodeKind::Symbol => vec![("sym", node.span.start, node.span.end)],
        NodeKind::Dot => vec![("dot", node.span.start, node.span.end)],
        NodeKind::Integer => vec![("int", node.span.start, node.span.end)],
        NodeKind::Real => vec![("real", node.span.start, node.span.end)],
        NodeKind::String => vec![("str", node.span.start, node.span.end)],
        NodeKind::True => vec![("t", node.span.start, node.span.end)],
        NodeKind::Nil => vec![("nil", node.span.start, node.span.end)],
        NodeKind::Quote(child) => {
            let mut v = vec![("quote", node.span.start, node.span.end)];
            v.extend(label(child.as_ref()));
            v
        }
        NodeKind::Missing => vec![("missing", node.span.start, node.span.end)],
        NodeKind::Skipped => vec![("skipped", node.span.start, node.span.end)],
    }
}

/// Property: parse `src`, then for every node
///   - the span lies inside source bounds
///   - every child span is inside its parent's span
///   - sibling spans are ordered and non-overlapping
fn assert_well_nested(src: &str) {
    let tokens = tokenize(src);
    let ast = parse(tokens, src);
    let mut prev_end = None;
    assert_eq!(
        ast.root.span,
        (0..src.len()).into(),
        "Root span is not total"
    );
    if let Node {
        span: s,
        kind: NodeKind::Root(children),
    } = ast.root
    {
        for child in &children {
            prev_end = assert_nested_node(child, s, prev_end);
        }
    } else {
        panic!("Root node is {} not TokenKind::Root", label(&ast.root)[0].0);
    }
}

fn assert_nested_node(
    node: &Node,
    parent_span: Span,
    mut prev_end: Option<usize>,
) -> Option<usize> {
    assert!(
        node.span.start >= parent_span.start,
        "Node ({:?}) starts before parent {parent_span:?}.",
        label(node)[0]
    );
    assert!(
        node.span.end <= parent_span.end,
        "Node ({:?}) ends after parent {parent_span:?}.",
        label(node)[0]
    );
    if let Some(prev) = prev_end {
        assert!(
            node.span.start >= prev,
            "Node {:?} starts before sibling ends {parent_span:?}.",
            node.span
        );
    };
    match &node.kind {
        NodeKind::Root(v) | NodeKind::List(v) => {
            prev_end = None;
            for child in v {
                prev_end = assert_nested_node(child, node.span, prev_end);
            }
            prev_end
        }
        NodeKind::Quote(n) => assert_nested_node(n, node.span, None),
        _ => Some(node.span.end),
    }
}

