// robustness
// ---------------------------------------------------------------

#[test]
fn test_never_panics_on_garbage() {
    for s in [
        "\"",
        ";|",
        "\\",
        ")(",
        "'",
        ".",
        "\u{0}",
        "\r\n\r\n",
        "|;",
        "é",
        "-",
        "((((",
        "(a . ",
        "(. a)",
        "( ' ",
        "))))",
        "'(",
        "(defun",
        "\n(defun",
        "(1 . 2 3)",
        "(.)",
        "(1 .)",
        "(1 . 2 . 3)",
        "'')",
        "((.",
        "NIL",
        "99999999999999999999",
    ] {
        let tokens = tokenize(s);
        let _ = parse(tokens, s);
    }
}
